SELECT json_build_object(
 'outlook',(SELECT json_agg(x) FROM (SELECT a.analysis_id id,a.etf_code etf,a.analysis_at at,a.status st,a.published_at pub,a.data_source src,a.previous_analysis_id IS NOT NULL has_prev,left(a.error_message,160) err,count(r.tool_run_id) runs,count(*) FILTER (WHERE r.status='failed') bad,min(r.started_at) t0,max(r.finished_at) t1,round(sum(extract(epoch FROM r.finished_at-r.started_at))::numeric,2) tool_s FROM outlook_analyses a LEFT JOIN tool_runs r ON r.outlook_analysis_id=a.analysis_id WHERE a.data_source<>'unknown' OR r.tool_run_id IS NOT NULL GROUP BY a.analysis_id ORDER BY min(r.started_at)) x),
 'movement',(SELECT json_agg(x) FROM (SELECT a.analysis_id id,a.etf_code etf,a.analysis_at at,a.status st,a.published_at pub,a.data_source src,a.previous_analysis_id IS NOT NULL has_prev,left(a.error_message,160) err,count(r.tool_run_id) runs,count(*) FILTER (WHERE r.status='failed') bad,min(r.started_at) t0,max(r.finished_at) t1,round(sum(extract(epoch FROM r.finished_at-r.started_at))::numeric,2) tool_s FROM movement_analyses a LEFT JOIN tool_runs r ON r.movement_analysis_id=a.analysis_id WHERE a.data_source<>'unknown' OR r.tool_run_id IS NOT NULL GROUP BY a.analysis_id ORDER BY min(r.started_at)) x)
) AS j
